 for(const n of neighbors(move)){if(replay[n]!==enemy)continue;const g=inspect(replay).groups.find(g=>g.stones.includes(n));if(g.liberties.length===0)for(const p of g.stones)removed.add(p);}
 for(const p of removed)replay[p]=".";
 if(removed.size){captures[color]+=removed.size;events.push({number:moves.length,color,move,removed:[...removed].sort()});}
 if(!inspect(replay).groups.find(g=>g.stones.includes(move)).liberties.length)throw Error("suicide recorded");
}
