 checks.push({response:i+1,throughMove:moves.length,boardMatches,captureMatches});
 if(!boardMatches||!captureMatches)throw Error("Replay mismatch");
}
const inv=inspect(replay),area={B:0,W:0,neutral:0},stones={B:0,W:0},territory={B:0,W:0},rows=[];
