const sgfCoord=p=>p==="pass"?"":String.fromCharCode(97+cols.indexOf(p[0]))+String.fromCharCode(97+9-Number(p[1]));
const sgf="(;GM[1]FF[4]CA[UTF-8]SZ[9]KM[7]RU[Chinese]DT[2026-10-06]PB[KataGo human-style 20k]PW[Codex]RE[W+20]"+moves.map(m=>";"+m.color+"["+sgfCoord(m.move)+"]").join("")+")\\n";
text(await tools.apply_patch("*** Begin Patch\\n*** Add File: game-032.sgf\\n+"+sgf.trimEnd()+"\\n*** End Patch"));
`+"})()");
